function I({registerIndicator:x,sourceValues:S,nulls:g}){x({id:"oa-reverseema",name:"Ehlers Reverse EMA (REVERSEEMA)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1,tooltip:"Lookback period for the base EMA."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"reverseema",type:"line",title:"REVERSEEMA",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86"}],calc(r,M){const F=Math.max(1,Math.floor(Number(M.period)||20)),L=S(r,M.source??"close"),l=2/(F+1),c=1-l,O=c,s=c*c,n=s*s,a=n*n,p=a*a,i=p*p,m=i*i,P=m*m;let k=!0,u=1,e=0,t=0,A=0,v=0,R=0,E=0,f=0,d=0,b=0,y=0,N=0;const w=new Array(r.length).fill(NaN);for(let o=0;o<r.length;o++){const h=L[o],W=Number.isFinite(h)?h:0;if(e=l*(W-e)+e,k){u*=O;const V=1-u;t=(V!==0?1/V:1)*e,k=u>1e-10}else t=e;const Z=A,j=v,q=R,z=E,B=f,C=d,D=b,G=y;v=c*t+Z,R=s*v+j,E=n*R+q,f=a*E+z,d=p*f+B,b=i*d+C,y=m*b+D,N=P*y+G,A=t,Number.isFinite(h)&&(w[o]=t-l*N)}return{reverseema:g(w)}}})}export{I as default};
